-- Rebuilds the `canvas:morning-briefing` workflow (id 0ad09fa0-…) from scratch.
--
-- The briefing that ran before 2026-07-29 fabricated most of its content: its
-- prompt interpolated the same merged `{{input}}` blob under four different
-- headings, and its system prompt told the model to "skip missing sections
-- silently" — so it filled the gaps with plausible invention (a sleep figure
-- when the health tool errored, an email count when Gmail's token had expired).
--
-- This graph makes that structurally impossible:
--   * every source is namespaced by its own `transform`, so provenance survives
--     the merge;
--   * `briefing-compose` renders a FACTS block of pre-formatted, unit-correct
--     values plus an explicit GAPS list, and a source ledger recording what each
--     signal actually did;
--   * the LLM may only quote FACTS verbatim and must never fill a GAP.
--
-- Weather is fetched twice — at home, and wherever `person.john` actually is —
-- so the briefing reflects local conditions when he is away.
--
-- Node ids are uuid5-derived, so re-running this is idempotent.
-- Apply with:
--   docker exec -i strange-rambling-app-db-1 psql -U app -d strange_rambling < this-file
BEGIN;
DELETE FROM workflow_edges WHERE workflow_id = '0ad09fa0-5e17-40c2-9438-0604d6071a22';
DELETE FROM workflow_nodes WHERE workflow_id = '0ad09fa0-5e17-40c2-9438-0604d6071a22';
UPDATE workflows SET trigger = $SR${"type": "cron", "config": {"expression": "0 7 * * *"}}$SR$::jsonb, description = $SR$Verified-source morning briefing. Gathers location, weather at home and where John actually is, health, home sensors, email and knowledge-graph context; composes a fact sheet the LLM may only quote verbatim; sends a WhatsApp summary and writes the full detail to /jkai/briefing.$SR$, updated_at = now() WHERE id = '0ad09fa0-5e17-40c2-9438-0604d6071a22';

-- Keep the structured memory rows alongside the fact sheet so the briefing UI
-- can show what JKAI learned as a first-class section, not only as prose.
UPDATE workflow_nodes
SET config = jsonb_set(
  config,
  '{expression}',
  to_jsonb(replace(
    config->>'expression',
    '    knowledge: b.knowledge || null,' || E'\n',
    '    knowledge: b.knowledge || null,' || E'\n' || '    memories: b.memories || [],' || E'\n'
  ))
)
WHERE id = '037b85f4-3707-5c5a-8592-df2b8873ecdf';

-- Memories are not optional colour once supplied: make the writer share at
-- least one of them explicitly in the outbound note.
UPDATE workflow_nodes
SET config = jsonb_set(
  config,
  '{systemPrompt}',
  to_jsonb((config->>'systemPrompt') || E'\n\nMEMORY: When FACTS contains New memories, include at least one “What I learned” bullet using those facts.')
)
WHERE id = 'dc7493f0-96f7-5c38-8358-d89e45f0be89';
COMMIT;
